def calculate_energy(mass_kg: float, velocity_mps: float) -> float:
    """Compute kinetic energy in Joules using E = 0.5 * m * v^2."""
    # 4-space block
    if mass_kg < 0 or velocity_mps < 0:
        raise ValueError("Physical values cannot be negative.")
    return 0.5 * mass_kg * (velocity_mps ** 2)

energy = calculate_energy(1200.0, 25.0)
print(f"Kinetic Energy: {energy:,.1f} J")
print(f"Docstring: {calculate_energy.__doc__}")

