#include <iostream>
#include <condition_variable>
#include <mutex>
#include <thread>

int main() {
    std::mutex m; std::condition_variable cv; bool ready = false;
    std::thread worker([&]{ std::lock_guard lk(m); ready = true; cv.notify_one(); });
    std::unique_lock lk(m);
    cv.wait(lk, [&]{ return ready; });
    worker.join();
    std::cout << "Notified!\n";
}

