CREATE DATABASE analytics_core;
\c analytics_core;

CREATE SCHEMA IF NOT EXISTS tenant_eu;
SET search_path TO tenant_eu, public;

-- Inspect current active schema
SELECT current_database(), current_schema();

CREATE TABLE app_users (
    user_id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    is_active     BOOLEAN DEFAULT TRUE,
    created_at    TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Non-blocking schema migration
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS tier VARCHAR(32) DEFAULT 'FREE';

-- Fast clean-up without scanning rows
TRUNCATE TABLE app_users RESTART IDENTITY;

CREATE TABLE product_catalog (
    product_id   UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    sku          VARCHAR(64) NOT NULL,
    price_usd    DECIMAL(12, 2) NOT NULL CHECK (price_usd >= 0),
    in_stock     BOOLEAN DEFAULT TRUE,
    released_on  DATE NOT NULL,
    attributes   JSONB NOT NULL DEFAULT '{}'::jsonb
);

INSERT INTO product_catalog (sku, price_usd, released_on, attributes)
VALUES ('DEV-4090', 1599.99, '2024-03-15', '{"ram_gb": 24, "tdp_watts": 450}');

SELECT sku, price_usd, attributes->>'ram_gb' AS ram
FROM product_catalog;

-- Composite index supporting leftmost prefix filters
CREATE INDEX idx_orders_customer_status 
ON orders (customer_id, order_status);

-- Covering index: satisfies query entirely from index leaf pages
CREATE INDEX idx_orders_covering 
ON orders (customer_id) INCLUDE (total_amount, created_at);

-- Query uses Index Only Scan (Heap Fetches: 0)
EXPLAIN SELECT customer_id, total_amount FROM orders WHERE customer_id = 42;

-- Standard virtual view
CREATE OR REPLACE VIEW v_active_orders AS
SELECT order_id, customer_id, total_amount
FROM orders
WHERE order_status = 'PAID';

-- Materialized view for fast analytics
CREATE MATERIALIZED VIEW mv_daily_sales AS
SELECT CAST(created_at AS DATE) AS sale_date, SUM(total_amount) AS revenue
FROM orders GROUP BY 1;

CREATE UNIQUE INDEX idx_mv_daily_sales ON mv_daily_sales (sale_date);
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_sales;

CREATE SEQUENCE invoice_seq
    START WITH 1000
    INCREMENT BY 1
    CACHE 20;

CREATE TABLE invoices (
    invoice_id   BIGINT PRIMARY KEY DEFAULT nextval('invoice_seq'),
    billing_code VARCHAR(32) NOT NULL
