-- M:N Relationship: Students <-> Courses via enrollment bridge table
CREATE TABLE students (
    student_id BIGINT PRIMARY KEY,
    full_name  VARCHAR(100) NOT NULL
);

CREATE TABLE courses (
    course_code VARCHAR(16) PRIMARY KEY,
    title       VARCHAR(120) NOT NULL
);

-- Associative junction table
CREATE TABLE enrollments (
    student_id   BIGINT REFERENCES students(student_id) ON DELETE CASCADE,
    course_code  VARCHAR(16) REFERENCES courses(course_code) ON DELETE CASCADE,
    enrolled_at  DATE DEFAULT CURRENT_DATE,
    grade        VARCHAR(2),
    PRIMARY KEY (student_id, course_code)
);

CREATE OR REPLACE PROCEDURE process_quarterly_bonus(
    IN p_dept_id INT,
    IN p_bonus_pct NUMERIC
)
LANGUAGE plpgsql
AS $$
BEGIN
    -- Perform update
    UPDATE employee_salaries
    SET bonus = salary * (p_bonus_pct / 100.0)
    WHERE department_id = p_dept_id;

    -- Explicit transaction control inside procedure
    COMMIT;
END;
$$;

-- Invoke procedure
CALL process_quarterly_bonus(10, 5.0);

CREATE OR REPLACE FUNCTION log_user_audit()
RETURNS TRIGGER 
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO audit_log (table_name, operation, record_id, changed_at)
    VALUES ('users', TG_OP, OLD.user_id, NOW());
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_user_audit
AFTER DELETE OR UPDATE ON users
FOR EACH ROW
EXECUTE FUNCTION log_user_audit();

